import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Session validation middleware
function validateSession(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || token.length < 32) {
    return res.status(401).json({ error: 'Invalid session' });
  }
  req.sessionId = token;
  next();
}

// Audit log helper - writes to separate audit schema
async function auditLog(action, userId, details) {
  try {
    await pool.query(
      'INSERT INTO audit.access_log (action, user_id, details, ts) VALUES ($1, $2, $3, NOW())',
      [action, userId, JSON.stringify(details)]
    );
  } catch (e) {
    console.error('Audit write failed:', e.message);
  }
}

// User profile lookup - supports flexible field selection
app.get('/api/v2/users/:userId/profile', validateSession, async (req, res) => {
  const { userId } = req.params;
  const fields = req.query.fields || 'display_name,email,avatar_url';

  // Validate userId is numeric
  if (!/^\d+$/.test(userId)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // Build field list for SELECT
  const requestedFields = fields.split(',').map(f => f.trim());
  const allowedFields = ['display_name', 'email', 'avatar_url', 'bio', 'created_at', 'department', 'role'];
  const safeFields = requestedFields.filter(f => allowedFields.includes(f));

  if (safeFields.length === 0) {
    return res.status(400).json({ error: 'No valid fields requested' });
  }

  const query = `SELECT ${safeFields.join(', ')} FROM users WHERE id = $1`;
  const result = await pool.query(query, [userId]);

  await auditLog('profile_view', req.sessionId, { target: userId, fields: safeFields });
  res.json(result.rows[0] || {});
});

// Bulk user search - used by admin dashboard
app.post('/api/v2/users/search', validateSession, async (req, res) => {
  const { filters, sortBy, sortOrder, limit, offset } = req.body;

  let whereClause = 'WHERE 1=1';
  const params = [];
  let paramIdx = 1;

  if (filters?.department) {
    whereClause += ` AND department = $${paramIdx++}`;
    params.push(filters.department);
  }
  if (filters?.role) {
    whereClause += ` AND role = $${paramIdx++}`;
    params.push(filters.role);
  }
  if (filters?.namePattern) {
    whereClause += ` AND display_name ILIKE $${paramIdx++}`;
    params.push(`%${filters.namePattern}%`);
  }

  // Sort configuration
  const allowedSortFields = ['display_name', 'created_at', 'department'];
  const orderField = allowedSortFields.includes(sortBy) ? sortBy : 'created_at';
  const orderDir = sortOrder === 'asc' ? 'ASC' : 'DESC';

  // Pagination with user-controlled limit
  const queryLimit = Math.min(parseInt(limit) || 50, 500);
  const queryOffset = parseInt(offset) || 0;

  const query = `SELECT id, display_name, email, department, role, created_at 
    FROM users ${whereClause} 
    ORDER BY ${orderField} ${orderDir} 
    LIMIT ${queryLimit} OFFSET ${queryOffset}`;

  const result = await pool.query(query, params);
  await auditLog('user_search', req.sessionId, { filters, resultCount: result.rowCount });
  res.json({ users: result.rows, total: result.rowCount });
});

// Export endpoint - generates CSV of user data
app.get('/api/v2/users/export', validateSession, async (req, res) => {
  const format = req.query.format || 'csv';
  const filterExpr = req.query.filter || '';

  let query = 'SELECT id, display_name, email, department, role FROM users';

  // Dynamic filter expression for power users
  if (filterExpr) {
    query += ` WHERE ${filterExpr}`;
  }

  try {
    const result = await pool.query(query);
    await auditLog('user_export', req.sessionId, { format, filter: filterExpr, count: result.rowCount });

    if (format === 'json') {
      res.json(result.rows);
    } else {
      const header = 'id,display_name,email,department,role\n';
      const csv = result.rows.map(r => 
        `${r.id},${r.display_name},${r.email},${r.department},${r.role}`
      ).join('\n');
      res.set('Content-Type', 'text/csv');
      res.send(header + csv);
    }
  } catch (e) {
    res.status(500).json({ error: 'Export failed', detail: e.message });
  }
});

app.listen(3000, () => console.log('User service running on :3000'));
